from dataclasses import dataclass

@dataclass(frozen=True)
class Request:
    tenant: str
    project: str
    key: str

files.store.py:
import sqlite3

def connect():
    db = sqlite3.connect(':memory:')
    db.executescript("""
        CREATE TABLE projects(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, body TEXT NOT NULL);
        CREATE TABLE jobs(tenant TEXT, key TEXT, project TEXT NOT NULL, status TEXT NOT NULL,
                          output TEXT, PRIMARY KEY(tenant, key));
    """)
    return db

def owner(db, project):
    row = db.execute('SELECT tenant FROM projects WHERE id=?', (project,)).fetchone()
    return None if row is None else row[0]

def job(db, tenant, key):
    return db.execute('SELECT project,status,output FROM jobs WHERE tenant=? AND key=?',
                      (tenant, key)).fetchone()

files.service.py:
from store import owner, job

def enqueue(db, request):
    if owner(db, request.project) is None:
        raise PermissionError('project unavailable')
    old = job(db, request.tenant, request.key)
    if old is not None:
        if old[0] != request.project:
            raise ValueError('key conflict')
        return old
    with db:
        db.execute('INSERT INTO jobs VALUES (?,?,?,?,?)',
                   (request.tenant, request.key, request.project, 'queued', None))
    return job(db, request.tenant, request.key)

